#!/usr/bin/env python3
"""Engine-independent, real-ID source-selection cases over fixed v0.7.0.

Does not import/read a phase3 engine, does not modify original records, and
does not treat an individual-year source quote as a comparable time series.
"""
from __future__ import annotations
import collections,datetime,decimal,gzip,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(path):return [json.loads(s) for s in path.read_text().splitlines()]

def main():
 root=ROOT;assert (root/'VERSION').read_text().strip()=='0.7.0'
 files=['VERSION','data/combined/observations.jsonl','derived/phase1_local_sources_long.jsonl','derived/ncl_2005_programmes_long.jsonl','derived/phase2/annotations.jsonl.gz','derived/phase2/evidence_cards.jsonl']
