 allrows=canon+local+programmes;byid={r['observation_id']:r for r in allrows};assert len(byid)==len(allrows)
 def choose(pred,n=1,pool=canon):
  rows=sorted((r for r in pool if pred(r)),key=lambda r:r['observation_id']);assert len(rows)>=n,('case_source_not_found',n);return rows[:n]
 def one(pred,pool=canon):return choose(pred,pool=pool)[0]
